css:
.selat-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #16212e;
    background: linear-gradient(165deg, #eef2f6 0%, #e7eef3 55%, #e2ebf1 100%);
    border-radius: 18px;
}

.selat-container * {
    box-sizing: border-box;
}

.selat-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0b2540 0%, #143b5e 52%, #0f5466 100%);
    color: #f1f7fb;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(11, 37, 64, 0.32);
}

.selat-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.selat-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffce7a;
    background: rgba(255, 206, 122, 0.13);
    border: 1px solid rgba(255, 206, 122, 0.38);
    padding: 5px 14px;
    border-radius: 999px;
}

.selat-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cfe2ec;
}

.selat-engagement {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.selat-eng-card {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(22, 33, 46, 0.08);
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.selat-eng-sharp { border-left: 5px solid #2f6fd6; }
.selat-eng-smart { border-left: 5px solid #e0653f; }

.selat-eng-name {
    font-weight: 800;
    font-size: 0.92rem;
    letter-spacing: 0.5px;
}

.selat-eng-sharp .selat-eng-name { color: #2059bf; }
.selat-eng-smart .selat-eng-name { color: #c64e2c; }

.selat-eng-meta {
    font-size: 0.82rem;
    color: #5a6b7a;
    line-height: 1.42;
}

.selat-eng-vs {
    align-self: center;
    font-size: 1.1rem;
    font-weight: 800;
    color: #0f5466;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.selat-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #46596b;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.selat-period-counter #currentDay,
.selat-period-counter #maxPeriods {
    font-weight: 800;
    color: #0f5466;
}

.selat-round-name {
    background: rgba(15, 84, 102, 0.13);
    color: #0c4a5a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.selat-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b85f12;
    background: rgba(224, 130, 30, 0.14);
    border: 1px solid rgba(224, 130, 30, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.selat-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.selat-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(22, 33, 46, 0.08);
    border-top: 4px solid #143b5e;
}

.selat-card-progress { border-top-color: #0f5466; }
.selat-card-fit { border-top-color: #2f6fd6; }
.selat-card-cohesion { border-top-color: #e0653f; }
.selat-card-margin { border-top-color: #d6a017; }

.selat-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7d8d;
}

.selat-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0b2540;
    font-variant-numeric: tabular-nums;
}

.selat-card-progress .selat-value { color: #0f5466; }
.selat-card-fit .selat-value { color: #2059bf; }
.selat-card-cohesion .selat-value { color: #c64e2c; }
.selat-card-margin .selat-value { color: #b5870c; }

.selat-sublabel {
    font-size: 0.76rem;
    color: #76889a;
    line-height: 1.35;
}

.selat-card-margin.selat-margin-danger { border-top-color: #d64545; }
.selat-card-margin.selat-margin-danger .selat-value { color: #d64545; }
.selat-card-margin.selat-margin-good { border-top-color: #1f9e6f; }
.selat-card-margin.selat-margin-good .selat-value { color: #1f9e6f; }

.selat-card-progress.selat-progress-good .selat-value { color: #1f9e6f; }
.selat-card-cohesion.selat-cohesion-good .selat-value { color: #1f9e6f; }
.selat-card-cohesion.selat-cohesion-danger .selat-value { color: #d64545; }
.selat-card-fit.selat-fit-good .selat-value { color: #1f9e6f; }

.selat-burn-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #dfe6ec;
    color: #46596b;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.selat-burn-bar #burnDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #d64545;
    font-weight: 800;
}

.selat-burn-bar.selat-burn-low #burnDisplay { color: #1f9e6f; }
.selat-burn-bar.selat-burn-mid #burnDisplay { color: #b85f12; }

.selat-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #0f5466;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(22, 33, 46, 0.07);
}

.selat-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.selat-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0b2540;
    margin-bottom: 6px;
}

.selat-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3c4d5e;
}

.selat-briefing-text strong { color: #0f5466; }
.selat-briefing-text em { color: #c64e2c; font-style: italic; }
.selat-briefing-text .sharp { color: #2059bf; font-weight: 700; font-style: normal; }

.selat-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(22, 33, 46, 0.07);
}

.selat-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0b2540;
    border-bottom: 2px solid #e7ecf0;
    padding-bottom: 8px;
}

.selat-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c3d4e;
    margin: 14px 0 6px;
}

.selat-container select,
.selat-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c6d2db;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #16212e;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.selat-container select:focus,
.selat-container input[type="number"]:focus {
    outline: none;
    border-color: #0f5466;
    box-shadow: 0 0 0 3px rgba(15, 84, 102, 0.16);
}

.selat-container select option {
    background-color: #ffffff;
    color: #16212e;
}

.selat-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #0f5466;
}

.selat-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #46596b;
    margin-top: 4px;
}

.selat-range-readout span:nth-child(2) {
    color: #0f5466;
    font-weight: 800;
}

.selat-hint {
    font-size: 0.8rem;
    color: #76889a;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.selat-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.selat-container .btn-primary {
    background: linear-gradient(135deg, #0f5466 0%, #143b5e 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(15, 84, 102, 0.32);
}

.selat-container .btn-primary:hover {
    filter: brightness(1.08);
}

.selat-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c6d2db;
    color: #5a6b7a;
    background: transparent;
}

.selat-coach {
    background: linear-gradient(160deg, #0b2540 0%, #122f4c 100%);
    color: #dceaf2;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(11, 37, 64, 0.24);
}

.selat-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffce7a;
    margin-bottom: 8px;
}

.selat-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.selat-coach-body strong { color: #6fd0c0; }
.selat-coach-body em { color: #ffce7a; font-style: italic; }
.selat-coach-body .sharp { color: #7fb0f0; font-weight: 700; font-style: normal; }

.selat-history,
.selat-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(22, 33, 46, 0.07);
}

.selat-history h3,
.selat-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0b2540;
}

.selat-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3c4d5e;
}

.selat-container table#usfHistoryTable th {
    background: #eaf2f4;
    color: #0f5466;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6e3e6;
}

.selat-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f3;
    color: #3c4d5e;
}

.selat-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f6faf9;
}

.selat-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .selat-container {
        padding: 14px;
    }
    .selat-header h1 {
        font-size: 1.7rem;
    }
    .selat-engagement {
        flex-direction: column;
    }
    .selat-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .selat-value {
        font-size: 2rem;
    }
    .selat-clock {
        margin-left: 0;
    }
    .selat-period-counter {
        font-size: 0.88rem;
    }
    .selat-burn-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .selat-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (sss- prefix; Selat teal-navy theme) ---- */
.sss-completion { padding: 8px 4px 4px; }
.sss-cm-head { text-align: center; margin-bottom: 16px; }
.sss-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #1f7a8c; }
.sss-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #76889a; }
.sss-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #16303a; }
.sss-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.sss-cm-yes { background: rgba(31,122,140,0.15); color: #1f7a8c; border: 1px solid rgba(31,122,140,0.45); }
.sss-cm-mid { background: rgba(118,136,154,0.15); color: #5f7286; border: 1px solid rgba(118,136,154,0.42); }
.sss-cm-no  { background: rgba(200,64,52,0.12); color: #c84034; border: 1px solid rgba(200,64,52,0.42); }
.sss-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.sss-cm-metric { flex: 1 1 100px; min-width: 96px; background: rgba(31,122,140,0.07); border: 1px solid rgba(31,122,140,0.20); border-radius: 10px; padding: 10px 8px; text-align: center; }
.sss-cm-mv { display: block; font-size: 1.2rem; font-weight: 800; color: #1f7a8c; }
.sss-cm-ml { display: block; font-size: 0.66rem; margin-top: 4px; color: #76889a; text-transform: uppercase; letter-spacing: 0.03em; }
.sss-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #16303a; }
.sss-cm-insights { margin: 0; padding-left: 20px; }
.sss-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #37474f; }

