(function() {
    'use strict';

    class SmartSharpStuckAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Smart, Sharp, Stuck`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Selat Analytics / Bumi Telekom engagement).
            this.START_PROGRESS = 40;     // ~40% of client value delivered
            this.START_FIT = 38;          // skill-fit score (right skill on the binding constraint)
            this.START_COHESION = 54;     // team-cohesion index /100
            this.START_MARGIN = 9;        // projected margin % at run-rate (vs 35% target)
            this.START_BURN = 62;         // % of budget hours consumed
            this.TARGET_MARGIN = 35;      // margin target
            this.OVERRUN = 180;           // RM 180k projected overrun
            this.AUC = 0.84;              // model performance (already above 0.75 target)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    progress: this.START_PROGRESS,    // % of client value delivered
                    fit: this.START_FIT,              // skill-fit score /100
                    cohesion: this.START_COHESION,    // team cohesion /100
                    margin: this.START_MARGIN,        // engagement margin %
                    burn: this.START_BURN,            // % of budget hours consumed

                    // Sticky run-defining penalty flags — set when an error is committed,
                    // they GATE the top verdict and CAP KPIs; a later good round cannot wash them out.
                    sharpTunnelRun: false,            // diagnosed/treated the smart stall as a sharp one
                    effortOverFitRun: false,          // piled effort/weekend work instead of skill-fit
                    ownerlessRun: false,              // left the client relationship without a single owner
                    conflictAvoidedRun: false,        // never surfaced the conflict productively
                    dataDumpRun: false,               // delivered model performance instead of decisions
                    actionLearning: false,            // built the intervention as action learning
                    readoutFailed: false,             // the readout failed a third time

                    progressHistory: [this.START_PROGRESS],
                    fitHistory: [this.START_FIT],
                    cohesionHistory: [this.START_COHESION],
                    marginHistory: [this.START_MARGIN],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the concept's common errors — a blind
                // click-through (sharp-tunnel, ownerless, conflict-avoidant, data-dump)
                // must NOT auto-win.
                state.decisions = {
                    blocker: `sharp`,
                    critical: `auc`,
                    tag: `sharp`,
                    confidence: 35,
                    owner: `pod`,
                    scientists: `more`,
                    intervention: `offsite`,
                    emphasis: 30,
                    conflict: `hope`,
                    effort: `weekends`,
                    dose: 50,
                    event: `comply`,
                    readout: `datadump`,
                    pitch: `depth`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const bl = document.getElementById(`blockerInput`);
                const cr = document.getElementById(`criticalInput`);
                const tg = document.getElementById(`tagInput`);
                const cf = document.getElementById(`confidenceInput`);
                if (bl) decisions.blocker = bl.value;
                if (cr) decisions.critical = cr.value;
                if (tg) decisions.tag = tg.value;
                if (cf) decisions.confidence = parseInt(cf.value, 10);
                if (!Number.isFinite(decisions.confidence) || decisions.confidence < 0 || decisions.confidence > 100) {
                    warn(`warn_confidence_range`); return false;
                }
            } else if (round === 2) {
                const ow = document.getElementById(`ownerInput`);
                const sc = document.getElementById(`scientistsInput`);
                const iv = document.getElementById(`interventionInput`);
                if (ow) decisions.owner = ow.value;
                if (sc) decisions.scientists = sc.value;
                if (iv) decisions.intervention = iv.value;
                if (!decisions.owner || !decisions.intervention) { warn(`warn_select`); return false; }
            } else if (round === 3) {
                const em = document.getElementById(`emphasisInput`);
                const co = document.getElementById(`conflictInput`);
                const ef = document.getElementById(`effortInput`);
                const ds3 = document.getElementById(`doseInput`);
                if (em) decisions.emphasis = parseInt(em.value, 10);
                if (co) decisions.conflict = co.value;
                if (ef) decisions.effort = ef.value;
                if (ds3) decisions.dose = parseInt(ds3.value, 10);
                if (!Number.isFinite(decisions.emphasis) || decisions.emphasis < 0 || decisions.emphasis > 100) {
                    warn(`warn_emphasis_range`); return false;
                }
                if (!Number.isFinite(decisions.dose) || decisions.dose < 0 || decisions.dose > 100) {
                    warn(`warn_dose_range`); return false;
                }
            } else if (round === 4) {
                const ev = document.getElementById(`eventInput`);
                const re = document.getElementById(`readoutInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ev) decisions.event = ev.value;
                if (re) decisions.readout = re.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let progressDelta = 0, fitDelta = 0, cohesionDelta = 0, marginDelta = 0, burnDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // DIAGNOSE — smart, sharp, or both? The dominant blocker is smart.
                switch (d.blocker) {
                    case `smart`:
                        fitDelta += 14; cohesionDelta += 4; coachKey = `coach_r1_smart`; break;
                    case `sharp`:
                        // Sharp-tunnel vision: misreading a smart stall as a technical gap.
                        ds.sharpTunnelRun = true;
                        fitDelta -= 8; cohesionDelta -= 3; coachKey = `coach_r1_sharp`; break;
                    case `none`:
                        // "Just tired, add hours" — effort over fit.
                        ds.effortOverFitRun = true;
                        fitDelta -= 5; coachKey = `coach_r1_none`; break;
                }

                switch (d.critical) {
                    case `translation`:
                        fitDelta += 8; progressDelta += 3; if (coachKey === `coach_default` || d.blocker === `smart`) coachKey = `coach_r1_translation`; break;
                    case `sizing`:
                        // A genuine sharp gap exists, but naming it as THE single most critical gap
                        // misses the dominant smart blocker.
                        fitDelta += 1; break;
                    case `auc`:
                        // The model was never the problem (decision tree #1).
                        ds.sharpTunnelRun = true;
                        fitDelta -= 6; coachKey = `coach_r1_auc`; break;
                }

                switch (d.tag) {
                    case `smart`: fitDelta += 6; cohesionDelta += 3; break;
                    case `sharp`: fitDelta -= 4; cohesionDelta -= 2; break;
                    case `work`: fitDelta -= 2; break;
                }

                // Confidence the blocker is smart = how committed the diagnosis is.
                if (d.confidence >= 65 && d.blocker === `smart`) { fitDelta += 4; cohesionDelta += 2; }
                else if (d.confidence <= 25 && d.blocker !== `smart`) { fitDelta -= 2; }

                summaryKey = (d.blocker === `smart` && d.critical === `translation` && d.tag === `smart`) ? `sum_r1_good` :
                             (ds.sharpTunnelRun ? `sum_r1_sharp` : `sum_r1_weak`);
            } else if (round === 2) {
                // PLAN — re-role and design the intervention.
                switch (d.owner) {
                    case `single`:
                        progressDelta += 8; fitDelta += 7; cohesionDelta += 3; coachKey = `coach_r2_owner`; break;
                    case `datalead`:
                        // The sharp lead owning the client doubles down on the wrong skill family.
                        progressDelta += 1; fitDelta -= 3; coachKey = `coach_r2_datalead`; break;
                    case `pod`:
                        // Ownerless client relationship (decision tree #3): diffuse = no ownership.
                        ds.ownerlessRun = true;
                        progressDelta -= 5; cohesionDelta -= 3; coachKey = `coach_r2_ownerless`; break;
                }

                switch (d.scientists) {
                    case `redirect`:
                        // Freeze the strong model, redirect to the sharp gap that matters (sizing).
                        progressDelta += 9; fitDelta += 6; marginDelta += 2; burnDelta -= 2; break;
                    case `coach`:
                        // A mid-engagement course burns the deadline for little.
                        progressDelta -= 2; burnDelta += 2; coachKey = `coach_r2_coach`; break;
                    case `more`:
                        // More AUC on an already-strong model (decision tree #1): spend for nothing.
                        ds.sharpTunnelRun = true;
                        progressDelta -= 4; fitDelta -= 5; marginDelta -= 3; burnDelta += 4; coachKey = `coach_r2_more`; break;
                }

                switch (d.intervention) {
                    case `actionlearning`:
                        ds.actionLearning = true;
                        progressDelta += 10; fitDelta += 8; cohesionDelta += 6; coachKey = `coach_r2_actionlearning`; break;
                    case `seminar`:
                        progressDelta -= 2; cohesionDelta += 1; burnDelta += 2; coachKey = `coach_r2_seminar`; break;
                    case `offsite`:
                        // A heavy intervention that eats the deadline (decision tree #4).
                        progressDelta -= 6; cohesionDelta += 2; burnDelta += 6; marginDelta -= 2; coachKey = `coach_r2_offsite`; break;
                    case `none`:
                        // No intervention leaves the smart gap unaddressed.
                        fitDelta -= 4; cohesionDelta -= 2; coachKey = `coach_r2_nointervention`; break;
                }

                summaryKey = (d.owner === `single` && d.scientists === `redirect` && d.intervention === `actionlearning`) ? `sum_r2_good` :
                             (ds.ownerlessRun ? `sum_r2_ownerless` :
                             (d.intervention === `offsite` ? `sum_r2_heavy` : `sum_r2_weak`));
            } else if (round === 3) {
                // DECIDE — the unblocking moves. Skill-fit moves progress more than raw effort.
                const smartShare = d.emphasis / 100;     // 0..1 effort on smart work
                const dose = d.dose / 100;               // 0..1 of three weeks on learning/realignment

                // (1) Skill emphasis. The sharp work is abundant; the gap is smart.
                // A strong tilt toward smart work is the modelled choice; over-investing in
                // sharp (low smart share) actively destroys value.
                if (smartShare >= 0.6) {
                    progressDelta += 12 * smartShare; fitDelta += 12 * smartShare; cohesionDelta += 5;
                } else if (smartShare <= 0.3) {
                    // Pouring effort into the already-abundant sharp skill (decision tree #1 & #2).
                    ds.sharpTunnelRun = true;
                    progressDelta -= 8 * (1 - smartShare); fitDelta -= 9 * (1 - smartShare); marginDelta -= 2;
                    coachKey = `coach_r3_sharpheavy`;
                } else {
                    progressDelta += 3; fitDelta += 2;
                }

                // (2) The conflict move (decision tree #5).
                switch (d.conflict) {
                    case `coach_consultants`:
                        progressDelta += 7; fitDelta += 6; cohesionDelta += 6; coachKey = `coach_r3_conflictcoach`; break;
                    case `lead_takes`:
                        // Doing it for them solves today's scope but doesn't close the smart gap.
                        progressDelta += 3; cohesionDelta -= 2; coachKey = `coach_r3_leadtakes`; break;
                    case `hope`:
                        // Conflict avoidance — hoping it resolves itself.
                        ds.conflictAvoidedRun = true;
                        progressDelta -= 5; cohesionDelta -= 4; coachKey = `coach_r3_conflicthope`; break;
                }

                // (3) Effort vs fit (decision tree #2).
                switch (d.effort) {
                    case `redeploy`:
                        progressDelta += 6; fitDelta += 5; marginDelta += 2; burnDelta -= 1; break;
                    case `some`:
                        progressDelta += 2; burnDelta += 2; break;
                    case `weekends`:
                        // Pile on hours instead of changing skill-fit: burn climbs, margin goes backwards.
                        ds.effortOverFitRun = true;
                        progressDelta += 1; burnDelta += 12; marginDelta -= 4; cohesionDelta -= 3; coachKey = `coach_r3_weekends`; break;
                }

                // (4) The intervention dose. Action learning happens THROUGH the task: a
                // moderate dose serves it; a heavy dose eats the deadline; near-zero leaves the gap.
                if (dose >= 0.85) {
                    progressDelta -= 7; burnDelta += 4; coachKey = `coach_r3_dosehigh`;
                } else if (dose <= 0.15) {
                    fitDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r3_doselow`;
                } else {
                    fitDelta += 4; cohesionDelta += 2;
                }

                if (smartShare >= 0.6 && d.conflict === `coach_consultants` && d.effort === `redeploy` && dose > 0.15 && dose < 0.85) {
                    coachKey = `coach_r3_skillfit`;
                }

                summaryKey = (smartShare >= 0.6 && d.conflict === `coach_consultants` && d.effort === `redeploy`) ? `sum_r3_good` :
                             (ds.effortOverFitRun ? `sum_r3_effort` :
                             (ds.sharpTunnelRun ? `sum_r3_sharp` :
                             (ds.conflictAvoidedRun ? `sum_r3_conflict` : `sum_r3_weak`)));
            } else if (round === 4) {
                // RECOVER & DELIVER — hold the diagnosis under pressure; close the translation gap.
                switch (d.event) {
                    case `reframe`:
                        progressDelta += 8; fitDelta += 6; cohesionDelta += 3; coachKey = `coach_r4_reframe`; break;
                    case `defer`:
                        // Avoiding the conflict instead of confronting it productively.
                        ds.conflictAvoidedRun = true;
                        progressDelta -= 2; cohesionDelta -= 2; coachKey = `coach_r4_defer`; break;
                    case `comply`:
                        // Regression to "just do more analysis" under pressure (decision tree #1).
                        ds.sharpTunnelRun = true;
                        progressDelta -= 6; fitDelta -= 5; marginDelta -= 3; burnDelta += 6; coachKey = `coach_r4_comply`; break;
                }

                switch (d.readout) {
                    case `decisions`:
                        progressDelta += 14; fitDelta += 8; coachKey = `coach_r4_decisions`; break;
                    case `hybrid`:
                        progressDelta += 4; coachKey = `coach_r4_hybrid`; break;
                    case `datadump`:
                        // Data-dump readout (decision tree #6): repeats the very failure.
                        ds.dataDumpRun = true;
                        progressDelta -= 8; cohesionDelta -= 1; coachKey = `coach_r4_datadump`; break;
                }

                switch (d.pitch) {
                    case `translate`:
                        progressDelta += 9; fitDelta += 6; if (d.readout === `decisions`) coachKey = `coach_r4_translate`; break;
                    case `apologise`:
                        progressDelta -= 2; cohesionDelta -= 1; coachKey = `coach_r4_apologise`; break;
                    case `depth`:
                        // Showcasing depth to a board that already rejected AUC twice.
                        ds.dataDumpRun = true;
                        progressDelta -= 5; coachKey = `coach_r4_depth`; break;
                }

                if (d.conviction >= 65) { fitDelta += 3; cohesionDelta += 1; }
                else if (d.conviction <= 25) { fitDelta -= 2; }

                summaryKey = (d.event === `reframe` && d.readout === `decisions` && d.pitch === `translate`) ? `sum_r4_good` :
                             (ds.dataDumpRun ? `sum_r4_datadump` :
                             (ds.sharpTunnelRun ? `sum_r4_sharp` : `sum_r4_weak`));
            }

            // ---- Apply deltas (clamped). ----
            ds.progress = Math.max(0, Math.min(100, Math.round(ds.progress + progressDelta)));
            ds.fit = Math.max(0, Math.min(100, Math.round(ds.fit + fitDelta)));
            ds.cohesion = Math.max(0, Math.min(100, Math.round(ds.cohesion + cohesionDelta)));
            ds.burn = Math.max(0, Math.min(120, Math.round(ds.burn + burnDelta)));

            // ---- Margin is DERIVED: it improves when value is delivered efficiently and
            // erodes as hours are burned past the value produced. Sharp-tunnel / effort-over-fit
            // both drive burn up and value flat -> margin collapses (decision tree #1 & #2). ----
            const efficiency = ds.progress - (ds.burn - this.START_BURN); // value vs extra burn
            let derivedMargin = this.START_MARGIN + (efficiency - this.START_PROGRESS) * 0.55 + marginDelta;
            ds.margin = Math.max(-20, Math.min(this.TARGET_MARGIN + 5, Math.round(derivedMargin)));

            // ---- Sticky penalty flags GATE the top verdict and CAP KPIs. A blown
            // diagnosis cannot be washed out by a later good round. ----
            if (ds.sharpTunnelRun) {
                // The model was never the problem — the readout fails a third time; progress caps.
                ds.readoutFailed = true;
                ds.progress = Math.min(ds.progress, 55);
                ds.fit = Math.min(ds.fit, 50);
            }
            if (ds.ownerlessRun) {
                // Scope drifts unchallenged with no owner — progress and fit are capped.
                ds.progress = Math.min(ds.progress, 65);
                ds.fit = Math.min(ds.fit, 60);
            }
            if (ds.effortOverFitRun) {
                // Mis-deployed effort: margin is capped low (you go backwards on margin).
                ds.margin = Math.min(ds.margin, 14);
            }
            if (ds.conflictAvoidedRun) {
                // Cohesion never recovers while the conflict is unsurfaced.
                ds.cohesion = Math.min(ds.cohesion, 62);
            }
            if (ds.dataDumpRun) {
                // A data-dump readout repeats the failure: progress (client value) is capped.
                ds.readoutFailed = true;
                ds.progress = Math.min(ds.progress, 60);
            }

            ds.progressHistory.push(ds.progress);
            ds.fitHistory.push(ds.fit);
            ds.cohesionHistory.push(ds.cohesion);
            ds.marginHistory.push(ds.margin);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist composite score + grade to the reporting/grading layer every period.
            // (results_utils.php::express_resolveDomainScore -> performance.overallScore). Scoring UNCHANGED.
            const _score = this._composite(ds);
            ds.performance = { overallScore: _score, grade: this._gradeLetter(_score) };

            return {
                period: state.currentPeriod,
                progress: ds.progress,
                progressDelta: Math.round(progressDelta),
                fit: ds.fit,
                fitDelta: Math.round(fitDelta),
                cohesion: ds.cohesion,
                cohesionDelta: Math.round(cohesionDelta),
                margin: ds.margin,
                burn: ds.burn,
                readoutFailed: ds.readoutFailed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                overallScore: _score,
                score: _score
            };
        }

        _burnLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            return `${Math.round(v)}%`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`progressDisplay`, `domainState.progress`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.selat-card-progress`);
                if (card) card.classList.toggle(`selat-progress-good`, n >= 80);
                return `${n}%`;
            });

            uiManager.bind(`fitDisplay`, `domainState.fit`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.selat-card-fit`);
                if (card) card.classList.toggle(`selat-fit-good`, n >= 70);
                return `${n}`;
            });

            uiManager.bind(`cohesionDisplay`, `domainState.cohesion`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.selat-card-cohesion`);
                if (card) {
                    card.classList.toggle(`selat-cohesion-good`, n >= 70);
                    card.classList.toggle(`selat-cohesion-danger`, n < 45);
                }
                return `${n}`;
            });

            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.selat-card-margin`);
                if (card) {
                    card.classList.toggle(`selat-margin-danger`, n < 15);
                    card.classList.toggle(`selat-margin-good`, n >= self.TARGET_MARGIN - 5);
                }
                return `${n}%`;
            });

            uiManager.bind(`burnDisplay`, `domainState.burn`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.selat-burn-bar`);
                if (bar) {
                    bar.classList.toggle(`selat-burn-low`, n < 70);
                    bar.classList.toggle(`selat-burn-mid`, n >= 70 && n < 90);
                }
                return self._burnLabel(n);
            });

            // Confidence slider readout.
            const cf = document.getElementById(`confidenceInput`);
            const cfReadout = document.getElementById(`confidenceReadout`);
            if (cf && cfReadout) {
                cfReadout.textContent = cf.value;
                cf.addEventListener(`input`, function() { cfReadout.textContent = cf.value; });
            }

            // Emphasis slider readout.
            const em = document.getElementById(`emphasisInput`);
            const emReadout = document.getElementById(`emphasisReadout`);
            if (em && emReadout) {
                emReadout.textContent = em.value;
                em.addEventListener(`input`, function() { emReadout.textContent = em.value; });
            }

            // Dose slider readout.
            const dose = document.getElementById(`doseInput`);
            const doseReadout = document.getElementById(`doseReadout`);
            if (dose && doseReadout) {
                doseReadout.textContent = dose.value;
                dose.addEventListener(`input`, function() { doseReadout.textContent = dose.value; });
            }
        }

        getChartConfig() {
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : null;
            const L = (k, en) => (t ? t(k) : en);
            return {
                selatPodChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: L(`chart_ds_progress`, `Project progress (%)`),
                                data: [],
                                borderColor: `#0f5466`,
                                backgroundColor: `rgba(15,84,102,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#0f5466`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_fit`, `Skill-fit score`),
                                data: [],
                                borderColor: `#2f6fd6`,
                                backgroundColor: `rgba(47,111,214,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f6fd6`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_cohesion`, `Team cohesion`),
                                data: [],
                                borderColor: `#e0653f`,
                                backgroundColor: `rgba(224,101,63,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#e0653f`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#46596b`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#76889a` }, grid: { color: `rgba(22,33,46,0.06)` },
                                title: { display: true, text: L(`chart_axis_scale`, `0–100`), color: `#76889a` }
                            },
                            x: {
                                ticks: { color: `#76889a` }, grid: { color: `rgba(22,33,46,0.04)` },
                                title: { display: true, text: L(`chart_axis_round`, `Round`), color: `#76889a` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.progressHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                selatPodChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.progressHistory },
                        { data: ds.fitHistory },
                        { data: ds.cohesionHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const progress = Math.round(ds.progress);
            const fit = Math.round(ds.fit);
            const cohesion = Math.round(ds.cohesion);
            const margin = Math.round(ds.margin);
            const marginScore = Math.max(0, Math.min(100, (margin / this.TARGET_MARGIN) * 100));
            return Math.round(progress * 0.34 + fit * 0.28 + cohesion * 0.20 + marginScore * 0.18);
        }

        _verdictKey(ds, composite) {
            const progress = Math.round(ds.progress);
            const fit = Math.round(ds.fit);
            const cohesion = Math.round(ds.cohesion);
            const margin = Math.round(ds.margin);
            const delivered = progress >= 80;
            const wellFit = fit >= 70;
            const cohesive = cohesion >= 68;
            const profitable = margin >= this.TARGET_MARGIN - 8;
            const cleanRun = !ds.sharpTunnelRun && !ds.ownerlessRun && !ds.effortOverFitRun &&
                             !ds.conflictAvoidedRun && !ds.dataDumpRun && !ds.readoutFailed;
            if (delivered && wellFit && cohesive && profitable && cleanRun && composite >= 78) return `verdict_landed`;
            if (ds.sharpTunnelRun && !ds.actionLearning) return `verdict_sharptunnel`;
            if (ds.dataDumpRun) return `verdict_datadump`;
            if (ds.effortOverFitRun) return `verdict_effort`;
            if (ds.ownerlessRun) return `verdict_ownerless`;
            if (ds.conflictAvoidedRun) return `verdict_conflict`;
            if (composite >= 60 && progress >= 65) return `verdict_partial`;
            return `verdict_lost`;
        }

        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 75) return `B`;
            if (c >= 62) return `C`;
            if (c >= 50) return `D`;
            if (c >= 35) return `E`;
            return `F`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const progress = Math.round(ds.progress);
            const fit = Math.round(ds.fit);
            const cohesion = Math.round(ds.cohesion);
            const margin = Math.round(ds.margin);

            // Composite — weighted toward client value delivered and skill-fit.
            const composite = this._composite(ds);

            const delivered = progress >= 80;
            const wellFit = fit >= 70;
            const cohesive = cohesion >= 68;
            const profitable = margin >= this.TARGET_MARGIN - 8;   // within striking distance of 35%
            const cleanRun = !ds.sharpTunnelRun && !ds.ownerlessRun && !ds.effortOverFitRun &&
                             !ds.conflictAvoidedRun && !ds.dataDumpRun && !ds.readoutFailed;

            // Verdict — the headline anti-pattern (sharp-tunnel / data-dump) CANNOT reach
            // the top verdict; sticky flags gate it.
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const verdictKey = this._verdictKey(ds, composite);
            const performance = T(verdictKey);

            let pattern = `mixed`;
            if (cleanRun && delivered && wellFit) pattern = `skillfit`;
            else if (ds.sharpTunnelRun) pattern = `sharptunnel`;
            else if (ds.dataDumpRun) pattern = `datadump`;
            else if (ds.effortOverFitRun) pattern = `effort`;

            const insights = [];
            if (verdictKey === `verdict_landed`) insights.push(window.mySimulation.t(`insight_landed`));
            else if (ds.sharpTunnelRun) insights.push(window.mySimulation.t(`insight_sharptunnel`));
            else if (ds.dataDumpRun) insights.push(window.mySimulation.t(`insight_datadump`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.ownerlessRun) insights.push(window.mySimulation.t(`insight_ownerless`));
            if (ds.conflictAvoidedRun) insights.push(window.mySimulation.t(`insight_conflict`));
            if (ds.effortOverFitRun) insights.push(window.mySimulation.t(`insight_effort`));
            if (ds.actionLearning && wellFit) insights.push(window.mySimulation.t(`insight_actionlearning`));
            if (wellFit && progress >= 80 && cohesion < 68) insights.push(window.mySimulation.t(`insight_cohesion_lag`));

            return {
                progress: progress,
                fit: fit,
                cohesion: cohesion,
                margin: margin,
                delivered: delivered,
                wellFit: wellFit,
                cohesive: cohesive,
                profitable: profitable,
                readoutFailed: ds.readoutFailed,
                cleanRun: cleanRun,
                pattern: pattern,
                composite: composite,
                overallScore: composite,
                verdictKey: verdictKey,
                grade: this._gradeLetter(composite),
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const s = summary || {};
            const score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            const grade = s.grade || '';
            const verdict = s.performance || (s.verdictKey ? T(s.verdictKey) : '');
            const progress = Math.round(Number(s.progress || 0)) + '%';
            const fit = Math.round(Number(s.fit || 0));
            const cohesion = Math.round(Number(s.cohesion || 0));
            const margin = Math.round(Number(s.margin || 0)) + '%';
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map((t) => '<li>' + t + '</li>').join('');
            const landed = s.verdictKey === 'verdict_landed';
            const badgeCls = landed ? 'sss-cm-yes' : (score >= 62 ? 'sss-cm-mid' : 'sss-cm-no');
            const metric = (val, lab) => '<div class="sss-cm-metric"><span class="sss-cm-mv">' + val + '</span><span class="sss-cm-ml">' + lab + '</span></div>';
            const metrics = metric(progress, T('cm_m_progress'))
                + metric(fit, T('cm_m_fit'))
                + metric(cohesion, T('cm_m_cohesion'))
                + metric(margin, T('cm_m_margin'));
            return ''
                + '<div class="sss-completion">'
                +   '<div class="sss-cm-head">'
                +     '<div class="sss-cm-score">' + score + '<span class="sss-cm-score-max">/100</span></div>'
                +     '<div class="sss-cm-grade">' + verdict + ' <span class="sss-cm-badge ' + badgeCls + '">' + T('cm_grade') + ' ' + grade + '</span></div>'
                +   '</div>'
                +   '<div class="sss-cm-metrics">' + metrics + '</div>'
                +   '<div class="sss-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="sss-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.sharpTunnelRun) return window.mySimulation.t(`hint_sharptunnel`);
            if (ds.dataDumpRun) return window.mySimulation.t(`hint_datadump`);
            if (ds.ownerlessRun && state.currentPeriod >= 2) return window.mySimulation.t(`hint_ownerless`);
            if (ds.effortOverFitRun) return window.mySimulation.t(`hint_effort`);
            if (ds.conflictAvoidedRun && state.currentPeriod >= 3) return window.mySimulation.t(`hint_conflict`);
            if (ds.progress >= 80 && ds.fit >= 70 && ds.cohesion >= 68) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.progress`, label: `Progress`, i18nKey: `col_progress`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.fit`, label: `Skill-Fit`, i18nKey: `col_fit`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.cohesion`, label: `Cohesion`, i18nKey: `col_cohesion`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.margin`, label: `Margin`, i18nKey: `col_margin`, formatter: (v) => `${Math.round(v)}%` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
